     struct boot {
         unsigned char drive;
         unsigned char part;
         unsigned char offset;
         unsigned char size;
     } boots[3];
     boots[0].drive = 0x5C;
     boots[0].part = 1;
     boots[0].offset = 0;
     boots[0].size = 4096;

     boots[1].drive = 0x5C;
     boots[1].part = 2;
     boots[1].offset = 0;
     boots[1].size = 4096;

     boots[2].drive = 0x5C;
     boots[2].part = 3;
     boots[2].offset = 0;
     boots[2].size = 4096;
     ```

